(()=>{
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mini=document.getElementById('mini-map'),mctx=mini.getContext('2d');
const $=id=>document.getElementById(id), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), rnd=(a,b)=>a+Math.random()*(b-a);
const TILE_W=72,TILE_H=36,MAP_W=44,MAP_H=34;
const baseStats={Warrior:{str:9,dex:6,vit:9,int:3,mag:3},Wizard:{str:3,dex:5,vit:5,int:9,mag:9},Spellblade:{str:6,dex:6,vit:7,int:6,mag:6}};
const classCopy={Warrior:'A stalwart front-line fighter who favors steel and heavy armor.',Wizard:'A scholar of the old arts. Fragile, but deadly at a distance.',Spellblade:'A balanced battle-mage, equally at home with blade or spell.'};
const game={started:false,zone:'town',player:{name:'Wayfarer',nation:'Aresden',class:'Warrior',x:13,y:16,level:1,xp:0,hp:100,mp:40,stats:{...baseStats.Warrior},kills:0,coins:12},inventory:[],equipment:{Weapon:null,Head:null,Body:null,Hands:null,Feet:null,Charm:null},monsters:[],npcs:[],drops:[],particles:[],selected:null,nearby:null,quest:{accepted:false,kills:0,done:false},cooldowns:{},keys:{},modal:'create',action:'attack',potion:2,lastTime:0,saveAt:0,log:[],toastTimer:null,mouse:{x:0,y:0}};
const items={
 sword:{name:'Iron longsword',icon:'⚔',type:'Weapon',bonus:3,desc:'A plain but dependable blade. +3 melee damage.',value:18},
 bow:{name:'Ashwood bow',icon:'➶',type:'Weapon',bonus:2,desc:'A supple bow of pale ash. +2 ranged damage.',value:20},
 robe:{name:'Acolyte robe',icon:'♜',type:'Body',bonus:2,desc:'Threaded with a little warding magic. +2 defense.',value:16},
 amulet:{name:'Moonstone charm',icon:'◇',type:'Charm',bonus:1,desc:'Cool to the touch. +1 magic.',value:24},
 potion:{name:'Minor healing draught',icon:'⚗',type:'Consumable',desc:'Restores 45 health.',value:8},
 fang:{name:'Wolf fang',icon:'ᛉ',type:'Material',desc:'A trophy from a forest wolf.',value:3},
 pelt:{name:'Silverleaf pelt',icon:'◈',type:'Material',desc:'Unusually soft, faintly luminous.',value:12},
 ring:{name:'Signet of the March',icon:'◉',type:'Charm',bonus:2,desc:'A rare signet recovered from the wilds. +2 magic.',value:45}
};
const monsterTypes=[{kind:'wolf',name:'Forest wolf',icon:'🐺',hp:38,damage:7,xp:24,color:'#837966'},{kind:'slime',name:'Moss ooze',icon:'●',hp:29,damage:5,xp:18,color:'#9ba75f'},{kind:'bandit',name:'Roadside bandit',icon:'♟',hp:52,damage:9,xp:34,color:'#98644e'}];
function setCanvas(){const dpr=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',setCanvas);setCanvas();
function addLog(text,type=''){game.log.unshift({text,type});game.log=game.log.slice(0,4);$('log-lines').innerHTML=game.log.map(l=>`<div class="log-line ${l.type}">${l.text}</div>`).join('')}
function toast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
function save(){try{localStorage.setItem('emberfall-save',JSON.stringify({player:game.player,inventory:game.inventory,equipment:game.equipment,quest:game.quest,potion:game.potion,zone:game.zone}))}catch{}}
function loadSave(){try{const d=JSON.parse(localStorage.getItem('emberfall-save'));if(d?.player){game.player={...game.player,...d.player};game.inventory=d.inventory||[];game.equipment=d.equipment||game.equipment;game.quest=d.quest||game.quest;game.potion=d.potion??2;game.zone=d.zone||'town';game.started=true;game.modal=null;return true}}catch{}return false}
function seedWorld(){game.npcs=[{id:'rowan',name:'Captain Rowan',title:'Town watch',x:10.4,y:14.5,icon:'⚔',color:'#9c754b'},{id:'mara',name:'Mara the Provisioner',title:'Merchant',x:17.2,y:14.2,icon:'♙',color:'#9d7754'},{id:'selene',name:'Sister Selene',title:'Keeper of the shrine',x:14.3,y:10.8,icon:'✦',color:'#878cb0'}];game.monsters=[];let points=[[31,8,'wolf'],[35,12,'wolf'],[32,18,'slime'],[38,20,'bandit'],[29,24,'slime'],[39,7,'wolf'],[35,27,'wolf'],[41,14,'bandit']];points.forEach(([x,y,k],i)=>{const t=monsterTypes.find(m=>m.kind===k);game.monsters.push({...t,id:'m'+i,x:x+rnd(-.6,.6),y:y+rnd(-.6,.6),maxHp:t.hp,hp:t.hp,alive:true,homeX:x,homeY:y,attackAt:0})})}
seedWorld();
function boot(){if(!loadSave())showModal('create');else{addLog('The eastern road is quiet this morning.');updateUI()}}
function showModal(type,html){game.modal=type;const root=$('modal-root');root.innerHTML=html||'';root.classList.toggle('open',!!html);if(html)root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal())}
function closeModal(){game.modal=null;$('modal-root').innerHTML='';game.started=true;save()}
function modalWrap(content){return `<div class="modal-backdrop"><section class="modal">${content}</section></div>`}
function createScreen(){const html=modalWrap(`<h1>Chronicle of the Twin Crowns</h1><div class="eyebrow">A TALE FROM THE EASTERN MARCH · YEAR 417</div><p style="text-align:center;max-width:570px;margin:0 auto 15px">The borderlands stir beneath an uneasy peace. Choose your banner and calling, then take your first steps into the old kingdoms.</p><div class="creation-grid"><div><label class="field-label">YOUR NAME</label><input class="name-input" id="create-name" maxlength="16" value="Wayfarer" placeholder="Name your adventurer"><label class="field-label">CHOOSE A NATION</label><div class="choice-row" id="nation-choice"><div class="choice active" data-nation="Aresden"><strong>ARES﻿DEN</strong>Kingdom of the Lion</div><div class="choice" data-nation="Elvine"><strong>ELVINE</strong>Realm of the Crescent</div></div><p style="font-size:10px;margin-top:7px">Your allegiance shapes the colors you bear. This chronicle follows a lone traveler, not a networked world.</p></div><div><label class="field-label">CHOOSE YOUR CALLING</label><div class="class-list" id="class-choice">${Object.keys(baseStats).map((c,i)=>`<div class="class-card ${i===0?'active':''}" data-class="${c}"><b>${c}</b><p>${classCopy[c]}</p></div>`).join('')}</div><div class="stat-preview" id="stat-preview"></div></div></div><button class="primary-button" id="begin-btn">BEGIN YOUR CHRONICLE</button>`);
showModal('create',html);let nation='Aresden',chosen='Warrior';const preview=()=>{$('stat-preview').innerHTML=[['STR','str'],['DEX','dex'],['VIT','vit'],['INT','int'],['MAG','mag']].map(([a,b])=>`<span>${a}<b>${baseStats[chosen][b]}</b></span>`).join('')};preview();document.querySelectorAll('[data-nation]').forEach(e=>e.onclick=()=>{nation=e.dataset.nation;document.querySelectorAll('[data-nation]').forEach(x=>x.classList.toggle('active',x===e))});document.querySelectorAll('[data-class]').forEach(e=>e.onclick=()=>{chosen=e.dataset.class;document.querySelectorAll('[data-class]').forEach(x=>x.classList.toggle('active',x===e));preview()});$('begin-btn').onclick=()=>{const name=$('create-name').value.trim();if(!name){$('create-name').focus();return}game.player={...game.player,name:name.slice(0,16),nation,class:chosen,x:13,y:16,level:1,xp:0,hp:100,mp:chosen==='Warrior'?40:65,stats:{...baseStats[chosen]},kills:0,coins:12};game.inventory=[{id:'sword',qty:1},{id:'potion',qty:2},{id:'potion',qty:2},{id:'robe',qty:1}];game.equipment={Weapon:{id:'sword'},Head:null,Body:null,Hands:null,Feet:null,Charm:null};game.potion=2;game.zone='town';game.quest={accepted:false,kills:0,done:false};addLog(`Welcome to Greyhaven, ${name}.`);addLog('Find Captain Rowan by the well.','good');closeModal();updateUI()}}
function updateUI(){const p=game.player;$('player-name').textContent=p.name;$('player-class').textContent=`${p.class.toUpperCase()} · ${p.nation.toUpperCase()}`;$('level').textContent=p.level;$('hp-text').textContent=`${Math.ceil(p.hp)} / ${maxHp()}`;$('mp-text').textContent=`${Math.floor(p.mp)} / ${maxMp()}`;$('hp-fill').style.width=`${100*p.hp/maxHp()}%`;$('mp-fill').style.width=`${100*p.mp/maxMp()}%`;$('xp-fill').style.width=`${100*p.xp/xpNext()}%`;$('xp-text').textContent=`${p.xp} / ${xpNext()}`;$('potion-count').textContent=game.potion;$('bag-count').textContent=game.inventory.reduce((n,i)=>n+i.qty,0);$('location-name').textContent=game.zone==='town'?'GREYHAVEN':'WOLFWOOD';$('location-sub').textContent=`${p.nation} · ${game.zone==='town'?'Eastern March':'The Old Forest'}`;questUI()}
function maxHp(){return 80+game.player.stats.vit*5+(game.player.level-1)*12}function maxMp(){return 20+game.player.stats.mag*5+game.player.stats.int*3+(game.player.level-1)*8}function xpNext(){return 80+game.player.level*45}
function questUI(){let q=game.quest;if(q.done){$('quest-title').textContent='The Road Is Safer';$('quest-description').textContent='Captain Rowan has thanked you for your service.';$('quest-count').textContent='COMPLETE'}else if(!q.accepted){$('quest-title').textContent='A Quieting of the Wilds';$('quest-description').textContent='Speak with Captain Rowan near the town well.';$('quest-count').textContent='0 / 3'}else{$('quest-title').textContent='A Quieting of the Wilds';$('quest-description').textContent='Thin the beasts gathering along the eastern road.';$('quest-count').textContent=`${q.kills} / 3`}}

