function questUI(){let q=game.quest;if(q.done){$('quest-title').textContent='The Road Is Safer';$('quest-description').textContent='Captain Rowan has thanked you for your service.';$('quest-count').textContent='COMPLETE'}else if(!q.accepted){$('quest-title').textContent='A Quieting of the Wilds';$('quest-description').textContent='Speak with Captain Rowan near the town well.';$('quest-count').textContent='0 / 3'}else{$('quest-title').textContent='A Quieting of the Wilds';$('quest-description').textContent='Thin the beasts gathering along the eastern road.';$('quest-count').textContent=`${q.kills} / 3`}}
function iso(x,y,cx,cy,w,h){return {x:(x-y)*TILE_W/2+innerWidth/2-cx, y:(x+y)*TILE_H/2+innerHeight/2-cy+h}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawTile(x,y,cx,cy){const p=iso(x,y,cx,cy,0,0),isTown=x<27,road=isTown&&(Math.abs(y-17)<1.1||Math.abs(x-14)<1.0|| (x>8&&x<18&&y>10&&y<17));let col;if(isTown)col=road?'#9b8964':((x+y)%3===0?'#687b55':'#71845d');else col=((x*7+y*13)%7===0?'#4c6542':((x+y)%2?'#536f48':'#5a754c'));poly([{x:p.x,y:p.y},{x:p.x+TILE_W/2,y:p.y+TILE_H/2},{x:p.x,y:p.y+TILE_H},{x:p.x-TILE_W/2,y:p.y+TILE_H/2}],col,'rgba(24,36,23,.09)');if(road){poly([{x:p.x,y:p.y+2},{x:p.x+TILE_W/2-5,y:p.y+TILE_H/2},{x:p.x,y:p.y+TILE_H-3},{x:p.x-TILE_W/2+5,y:p.y+TILE_H/2}],(x+y)%2?'#9c8a67':'#a08e6b')}}
function drawTree(x,y,cx,cy,variant=0){const p=iso(x,y,cx,cy,0,0),z=p.y-TILE_H/2;ctx.fillStyle='#59452d';ctx.fillRect(p.x-3,z-13,6,18);const colors=['#344936','#3e553b','#465d3d','#3b5036'];ctx.fillStyle=colors[variant%4];ctx.beginPath();ctx.ellipse(p.x,z-20,13,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(153,164,101,.18)';ctx.beginPath();ctx.ellipse(p.x-4,z-25,6,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(22,31,20,.25)';ctx.beginPath();ctx.ellipse(p.x+8,z-13,5,6,0,0,Math.PI*2);ctx.fill()}
function drawHouse(x,y,cx,cy,variant=0){const p=iso(x,y,cx,cy,0,0),colors=[['#786246','#a28458','#503c2f'],['#68704d','#858a58','#493e31'],['#754c3d','#9d6650','#493631']][variant%3],w=82,h=58;ctx.fillStyle='#4b3b2b';ctx.fillRect(p.x-w/2,p.y-h+3,w,h);ctx.fillStyle=colors[0];ctx.beginPath();ctx.moveTo(p.x-w/2-7,p.y-h+9);ctx.lineTo(p.x,p.y-h-22);ctx.lineTo(p.x+w/2+7,p.y-h+9);ctx.closePath();ctx.fill();ctx.fillStyle=colors[1];ctx.beginPath();ctx.moveTo(p.x-w/2-7,p.y-h+9);ctx.lineTo(p.x,p.y-h-22);ctx.lineTo(p.x,p.y-h+12);ctx.closePath();ctx.fill();ctx.fillStyle=colors[2];ctx.fillRect(p.x-8,p.y-29,16,29);ctx.fillStyle='#d2aa68';ctx.fillRect(p.x-4,p.y-24,8,7);ctx.fillStyle='#d3bd8b';ctx.fillRect(p.x-27,p.y-43,11,10);ctx.fillRect(p.x+17,p.y-43,11,10);ctx.strokeStyle='#30271f';ctx.strokeRect(p.x-27,p.y-43,11,10);ctx.strokeRect(p.x+17,p.y-43,11,10)}
function drawScenery(cx,cy){let trees=[];for(let x=0;x<MAP_W;x++)for(let y=0;y<MAP_H;y++){if(x>=26&&((x*13+y*7)%6<2)&&!(x<30))trees.push([x,y,(x+y)%4]);if(x<26&&((x*9+y*17)%47===0)&&!(x>8&&x<20&&y>8&&y<19))trees.push([x,y,(x+y)%4)});trees.sort((a,b)=>a[0]+a[1]-b[0]-b[1]);trees.forEach(t=>drawTree(t[0],t[1],cx,cy,t[2]));[[7,7,0],[20,8,1],[7,20,2],[20,21,0],[3,12,1]].forEach(h=>drawHouse(h[0],h[1],cx,cy,h[2]));const well=iso(14,15,cx,cy,0,0);ctx.fillStyle='#716c54';ctx.beginPath();ctx.ellipse(well.x,well.y-2,17,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#283638';ctx.beginPath();ctx.ellipse(well.x,well.y-3,11,5,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a2936c';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(well.x,well.y-2,16,7,0,0,Math.PI*2);ctx.stroke();
const gate=iso(27,17,cx,cy,0,0);ctx.fillStyle='#65472f';ctx.fillRect(gate.x-4,gate.y-48,8,50);ctx.fillRect(gate.x+18,gate.y-48,8,50);ctx.fillStyle='#8c6741';ctx.fillRect(gate.x-8,gate.y-50,40,5);ctx.fillStyle='#a58955';ctx.fillRect(gate.x-2,gate.y-41,4,27);
}
function drawCharacter(x,y,cx,cy,kind,color,selected=false,name=''){const p=iso(x,y,cx,cy,0,0),floor=p.y;ctx.fillStyle='rgba(12,14,10,.35)';ctx.beginPath();ctx.ellipse(p.x,floor-3,12,5,0,0,Math.PI*2);ctx.fill();if(selected){ctx.strokeStyle='rgba(239,203,113,.75)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,floor-4,18,8,0,0,Math.PI*2);ctx.stroke()}
if(kind==='player'||kind==='npc'){ctx.fillStyle='#44372b';ctx.fillRect(p.x-7,floor-24,14,21);ctx.fillStyle=color;ctx.fillRect(p.x-9,floor-23,18,13);ctx.fillStyle='#d0ad7b';ctx.beginPath();ctx.arc(p.x,floor-29,7,0,Math.PI*2);ctx.fill();ctx.fillStyle=game.player.nation==='Aresden'?'#9b493c':'#565a95';if(kind==='player')ctx.fillRect(p.x-9,floor-12,18,3);ctx.fillStyle='#242018';ctx.fillRect(p.x-6,floor-7,4,5);ctx.fillRect(p.x+2,floor-7,4,5);if(kind==='player'){ctx.strokeStyle='#d2c4a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x+8,floor-21);ctx.lineTo(p.x+14,floor-8);ctx.stroke()}}
else{ctx.fillStyle=color;if(kind==='wolf'){ctx.beginPath();ctx.ellipse(p.x,floor-12,12,8,-.1,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(p.x+8,floor-16,6,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(p.x+10,floor-21);ctx.lineTo(p.x+12,floor-27);ctx.lineTo(p.x+15,floor-20);ctx.fill();ctx.fillStyle='#e2bb79';ctx.fillRect(p.x+10,floor-17,2,2)}else if(kind==='slime'){ctx.beginPath();ctx.ellipse(p.x,floor-9,11,7,0,Math.PI,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d5d597';ctx.fillRect(p.x-4,floor-12,2,2);ctx.fillRect(p.x+3,floor-12,2,2)}else{ctx.fillRect(p.x-7,floor-22,14,19);ctx.fillStyle='#bf9870';ctx.beginPath();ctx.arc(p.x,floor-27,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#423b33';ctx.fillRect(p.x-6,floor-8,4,7);ctx.fillRect(p.x+2,floor-8,4,7)}}
if(name){ctx.font='10px Spectral, serif';ctx.textAlign='center';ctx.lineWidth=3;ctx.strokeStyle='#12130f';ctx.strokeText(name,p.x,floor-41);ctx.fillStyle=selected?'#f0d892':'#e0d4b8';ctx.fillText(name,p.x,floor-41)}return p}

