function nearestTarget(max=4){let best=null,d=max;game.monsters.forEach(m=>{if(m.alive){const n=dist(game.player,m);if(n<d){best=m;d=n}}});return best}
function setTarget(m){game.selected=m;if(!m){$('target-card').classList.add('hidden');return} $('target-card').classList.remove('hidden');$('target-name').textContent=m.name;$('target-level').textContent=`Level ${m.kind==='bandit'?2:1} · ${m.kind==='wolf'?'Beast':m.kind==='slime'?'Aberration':'Humanoid'}`;updateTargetBar()}
function updateTargetBar(){const m=game.selected;if(m&&m.alive){$('target-hp-fill').style.width=`${100*m.hp/m.maxHp}%`; $('target-name').textContent=m.name}else if(m){setTarget(null)}}
function doAction(action=game.action){const p=game.player,t=game.selected;if(action==='potion'){if(game.potion<=0){toast('No healing draughts remain.');return}if(p.hp>=maxHp()){toast('You are already at full health.');return}game.potion--;p.hp=Math.min(maxHp(),p.hp+45);addLog('You drink a healing draught.','good');updateUI();return}
if(!t||!t.alive){t=nearestTarget(5);if(t)setTarget(t);else{toast('No foe in sight.');return}}const spell=action==='firebolt'||action==='heal',range=action==='arrow'||action==='firebolt'?8:2.1;if(action==='heal'){if(p.mp<12){toast('Not enough mana.');return}p.mp-=12;p.hp=Math.min(maxHp(),p.hp+36);game.particles.push({x:p.x,y:p.y,text:'+36',color:'#b8d78a',life:700,rise:26});addLog('A green light closes your wounds.','good');updateUI();return}if(dist(p,t)>range){toast(action==='attack'?'Move closer to strike.':'Your target is out of range.');return}const now=performance.now(),key=action;if((game.cooldowns[key]||0)>now)return;game.cooldowns[key]=now+(action==='attack'?690:action==='arrow'?1000:1300);let damage=action==='firebolt'?15+p.stats.mag*1.6:action==='arrow'?11+p.stats.dex:7+p.stats.str*.75+(items[game.equipment.Weapon?.id]?.bonus||0);if(spell){if(p.mp<8){toast('Not enough mana.');return}p.mp-=8;game.particles.push({x:t.x,y:t.y,text:'✦',color:'#e4a66e',life:450,rise:21})}else{game.particles.push({x:t.x,y:t.y,text:'-'+Math.round(damage),color:'#f3d9b6',life:560,rise:20})}t.hp-=damage;addLog(`${action==='firebolt'?'Firebolt':action==='arrow'?'Quickshot':'You strike'} hits ${t.name} for ${Math.round(damage)}.`);if(t.hp<=0)killMonster(t);updateTargetBar();updateUI()}
function killMonster(m){m.alive=false;game.player.xp+=m.xp;game.player.kills++;game.player.coins+=Math.floor(rnd(2,7));game.particles.push({x:m.x,y:m.y,text:`+${m.xp} XP`,color:'#e7cb78',life:1050,rise:22});addLog(`${m.name} falls. +${m.xp} experience.`,'good');if(Math.random()<.28){const id=Math.random()<.72?'fang':'pelt';game.drops.push({x:m.x,y:m.y,id,life:performance.now()+120000});addLog(`${items[id].name} dropped.`,'good')}if(Math.random()<.06){game.drops.push({x:m.x+.3,y:m.y,id:'ring',life:performance.now()+120000});addLog('A rare Moonlit signet gleams in the grass!','good')}if(game.quest.accepted&&!game.quest.done){game.quest.kills++;if(game.quest.kills>=3){game.quest.kills=3;addLog('The forest road is quieting. Return to Captain Rowan.','good')}questUI()}setTarget(null);checkLevel();setTimeout(()=>{m.x=m.homeX+rnd(-1,1);m.y=m.homeY+rnd(-1,1);m.hp=m.maxHp;m.alive=true},7000);updateUI()}
function checkLevel(){while(game.player.xp>=xpNext()){game.player.xp-=xpNext();game.player.level++;game.player.stats.vit++;game.player.stats.str++;game.player.stats.int++;game.player.hp=maxHp();game.player.mp=maxMp();toast(`Level ${game.player.level} — your strength grows!`);addLog(`You have reached level ${game.player.level}.`,'good')}}
function updateTargetRange(){if(game.selected&&game.selected.alive&&dist(game.player,game.selected)<= (game.action==='firebolt'||game.action==='arrow'?8:2.1)){if(performance.now()-(game.lastAttack||0)>80){doAction(game.action);game.lastAttack=performance.now()}}}
function nearbyInteraction(){let best=null,d=2.1;game.npcs.forEach(n=>{const x=dist(game.player,n);if(x<d){best=n;d=x}});game.nearby=best;const el=$('interact-prompt');if(best){el.classList.remove('hidden');$('interact-name').textContent=best.name}else el.classList.add('hidden')}
function interact(){if(game.nearby){talkTo(game.nearby);return}const drop=game.drops.find(d=>dist(game.player,d)<1.5);if(drop){addItem(drop.id);game.drops=game.drops.filter(d=>d!==drop);toast(`${items[drop.id].name} collected.`);return}if(game.player.x<29&&Math.abs(game.player.x-27)<2.5){game.zone='forest';game.player.x=29.4;game.player.y=17;toast('You pass beneath the eastern gate.');addLog('The old forest presses close to the road.','warn');updateUI();return}if(game.zone==='forest'&&game.player.x<29.5){game.zone='town';game.player.x=26.4;game.player.y=17;toast('Greyhaven’s lanterns welcome you.');updateUI();return}toast('There is nothing to interact with here.')}
function talkTo(n){if(n.id==='rowan'){if(game.quest.done){dialogue('Captain Rowan',`The road has been quiet since you drove the beasts back. Greyhaven owes you a debt, ${game.player.name}.`,`“I am glad to help.”`,`close`);return}if(!game.quest.accepted){dialogue('Captain Rowan','The wolves have grown bold, and something foul has stirred the moss-oozes east of the gate. Hunt three beasts along the forest road. Bring me word when it is done.','“I will see to it.”','accept-quest');return}if(game.quest.kills>=3){game.quest.done=true;game.player.coins+=35;game.player.xp+=70;game.player.inventory.push({id:'potion',qty:1});checkLevel();updateUI();dialogue('Captain Rowan','Well done, adventurer. The road can breathe again. Take these 35 crowns and a draught for your trouble.','“The March is safer now.”','close');addLog('Quest complete: A Quieting of the Wilds. +35 crowns, +70 XP.','good');save();return}dialogue('Captain Rowan',`The eastern road still needs your help. You have felled ${game.quest.kills} of the three beasts.`,`“I will return.”`,`close`)}else if(n.id==='mara')merchant();else dialogue('Sister Selene','Magic is not a weapon alone. A kind heart can be as mighty as a fire spell. Take this little blessing for the road.','“Thank you, Sister.”','bless')}
function dialogue(name,text,choice,action){const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">GREYHAVEN · EASTERN MARCH</div><h2>${name}</h2><p class="dialogue-text">${text}</p><div class="dialogue-options"><button id="dialogue-okay">${choice}</button></div>`);showModal('dialogue',html);$('dialogue-okay').onclick=()=>{if(action==='accept-quest'){game.quest.accepted=true;questUI();addLog('New quest: A Quieting of the Wilds.','good')}if(action==='bless'){game.player.mp=Math.min(maxMp(),game.player.mp+20);addLog('Sister Selene restores 20 mana.','good');updateUI()}closeModal()}}

