function dialogue(name,text,choice,action){const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">GREYHAVEN · EASTERN MARCH</div><h2>${name}</h2><p class="dialogue-text">${text}</p><div class="dialogue-options"><button id="dialogue-okay">${choice}</button></div>`);showModal('dialogue',html);$('dialogue-okay').onclick=()=>{if(action==='accept-quest'){game.quest.accepted=true;questUI();addLog('New quest: A Quieting of the Wilds.','good')}if(action==='bless'){game.player.mp=Math.min(maxMp(),game.player.mp+20);addLog('Sister Selene restores 20 mana.','good');updateUI()}closeModal()}}
function addItem(id,qty=1){const it=items[id];if(!it)return;let stack=game.inventory.find(v=>v.id===id);if(stack&&['Material','Consumable'].includes(it.type))stack.qty+=qty;else game.inventory.push({id,qty});updateUI();save()}
function equipItem(id){const it=items[id];if(!it)return;if(it.type==='Consumable'){if(game.potion<=0){toast('No healing draughts remain.');return}if(game.player.hp>=maxHp()){toast('You are already at full health.');return}game.potion--;game.player.hp=Math.min(maxHp(),game.player.hp+45);const s=game.inventory.find(v=>v.id==='potion');if(s){s.qty--;if(s.qty<=0)game.inventory=game.inventory.filter(v=>v!==s)}addLog('You drink a healing draught.','good');updateUI();openInventory();save();return}if(!['Weapon','Body','Head','Hands','Feet','Charm'].includes(it.type)){toast('This item has no use right now.');return}game.equipment[it.type]={id};const stack=game.inventory.find(v=>v.id===id);if(stack){stack.qty--;if(stack.qty<=0)game.inventory=game.inventory.filter(v=>v!==stack)}toast(`${it.name} equipped.`);updateUI();openInventory();save()}
function openInventory(){const rows=game.inventory.map((s,i)=>{const it=items[s.id];return `<div class="item-slot" data-item="${s.id}" title="${it.desc}"><span class="item-icon">${it.icon}</span><b>${it.name}</b><small>${it.type}</small>${s.qty>1?`<span class="qty">${s.qty}</span>`:''}</div>`}).join('')||'<p>Your pack is empty.</p>';const gear=Object.entries(game.equipment).map(([slot,entry])=>{const it=entry&&items[entry.id];return `<div class="gear-slot"><span>${it?it.icon:'◇'}</span>${slot}<br><b>${it?it.name:'—'}</b></div>`}).join('');const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">YOUR BELONGINGS</div><h2>Inventory & Equipment</h2><div class="inventory-layout"><div><label class="field-label">PACK · ${game.inventory.reduce((a,b)=>a+b.qty,0)} / 24</label><div class="slot-grid">${rows}</div><p style="font-size:10px">Select an item to equip or use it. You carry ${game.player.coins} crowns.</p></div><div><label class="field-label">EQUIPPED</label><div class="equipment-grid">${gear}</div><label class="field-label">ATTRIBUTES</label><div class="stats-list">${statRows()}</div></div></div>`);showModal('inventory',html);document.querySelectorAll('[data-item]').forEach(e=>e.onclick=()=>equipItem(e.dataset.item))}
function statRows(){return [['Strength','str'],['Dexterity','dex'],['Vitality','vit'],['Intelligence','int'],['Magic','mag']].map(([n,k])=>`<div class="stat-line"><span>${n}</span><b>${game.player.stats[k]}</b></div>`).join('')}
function openCharacter(){const p=game.player;const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">ADVENTURER'S RECORD</div><h2>${p.name}</h2><p>Level ${p.level} ${p.class} of ${p.nation}. You have felled ${p.kills} foes and carry ${p.coins} crowns.</p><div class="stats-list">${statRows()}<div class="stat-line"><span>Health</span><b>${Math.ceil(p.hp)} / ${maxHp()}</b></div><div class="stat-line"><span>Mana</span><b>${Math.floor(p.mp)} / ${maxMp()}</b></div><div class="stat-line"><span>Melee skill</span><b>${Math.floor(1+(p.kills*1.5))}</b></div><div class="stat-line"><span>Arcane skill</span><b>${Math.floor(1+(p.kills*.7))}</b></div></div><button class="primary-button" id="save-btn">SAVE CHRONICLE</button>`);showModal('character',html);$('save-btn').onclick=()=>{save();toast('Chronicle saved.')}}
function openSpellbook(){const spells=[['ϟ','Firebolt','8 mana · 15 + Magic damage','2'],['✚','Mend','12 mana · Restore 36 health','3'],['➶','Quickshot','Ranged attack · Dexterity','4'],['✧','Ember Ward','Passive · +2 resistance','Locked · Lv 3']];const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">THE OLD ARTS</div><h2>Spellbook</h2><p>Arcane practice improves as you grow. Spells marked with a key can be cast from the action bar.</p><div class="spell-list">${spells.map(s=>`<div class="spell-row"><i>${s[0]}</i><div><b>${s[1]}</b><small>${s[2]}</small></div><em>KEY ${s[3]}</em></div>`).join('')}</div>`);showModal('spellbook',html)}
function openSkills(){const skills=[['Swordplay','Steel & close combat',Math.floor(1+game.player.kills*1.5)],['Marksmanship','Bows & quick aim',Math.floor(1+game.player.kills)],['Sorcery','The old magic',Math.floor(1+game.player.kills*.7)],['Survival','Fieldcraft & endurance',Math.floor(1+game.player.kills*.4)]];const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">PRACTICE MAKES MIGHT</div><h2>Skills</h2><p>Skills gain experience through use. Keep hunting to master your chosen path.</p><div class="spell-list">${skills.map(s=>`<div class="spell-row"><i>⚒</i><div><b>${s[0]}</b><small>${s[1]}</small></div><em>RANK ${s[2]}</em></div>`).join('')}</div>`);showModal('skills',html)}
function merchant(){const offers=[['potion','Minor healing draught',8],['sword','Iron longsword',18],['bow','Ashwood bow',20],['robe','Acolyte robe',16]];const html=modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">GREYHAVEN · PROVISIONS</div><h2>Mara's Wares</h2><p>“A little something for the road? Fair prices, no questions.” You have <b>${game.player.coins}</b> crowns.</p><div class="spell-list">${offers.map(([id,n,c])=>`<div class="spell-row"><i>${items[id].icon}</i><div><b>${n}</b><small>${items[id].desc}</small></div><button class="tab-button buy" data-buy="${id}" data-cost="${c}">${c} crowns</button></div>`).join('')}</div>`);showModal('merchant',html);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const cost=+b.dataset.cost;if(game.player.coins<cost){toast('Not enough crowns.');return}game.player.coins-=cost;if(b.dataset.buy==='potion')game.potion++;addItem(b.dataset.buy);toast(`${items[b.dataset.buy].name} purchased.`);merchant();save()})}

