function showHelp(){showModal('help',modalWrap(`<button class="modal-close" data-close>×</button><div class="eyebrow">FIELD GUIDE</div><h2>Controls & Chronicle</h2><p>Explore Greyhaven and the forest beyond its eastern gate. Captain Rowan's task is optional, but the road is safer for it.</p><div class="help-grid"><div>Move <kbd>W A S D</kbd></div><div>Move <kbd>ARROW KEYS</kbd></div><div>Interact / collect <kbd>E</kbd></div><div>Target nearest foe <kbd>T</kbd></div><div>Attack / cast <kbd>1 — 4</kbd></div><div>Drink a draught <kbd>5</kbd></div><div>Inventory <kbd>I</kbd></div><div>Character <kbd>C</kbd></div><div>Spellbook <kbd>K</kbd></div><div>Skills <kbd>J</kbd></div><div>Close window <kbd>ESC</kbd></div><div>Walk to a point <kbd>CLICK</kbd></div></div><p style="font-size:10px">Your chronicle saves automatically in this browser. You may refresh safely.</p>`))}
